#!/usr/bin/env python3
"""Render the dependency-free, bilingual static Jivie site into public/."""
from html import escape
from pathlib import Path

ROOT = Path(__file__).resolve().parent / 'public'
PUBLISHER = 'TriparNA – kooperativa za sonaravno življenje in razvoj tehnologij samooskrbe, z.o.o.'
EMAIL = 'zadruga@triparna.si'


def url(lang, page=''):
    return ('/en/' if lang == 'en' else '/') + (page + '/' if page else '')


def brand(lang):
    return f'<a class="brand" href="{url(lang)}" aria-label="Jivie"><img src="/assets/jivie-icon.png" alt="" width="40" height="40">Jivie</a>'


def page(lang, slug, title, description, content, home=False):
    en = lang == 'en'
    other = 'sl' if en else 'en'
    text = dict(skip='Skip to content', everyday='Everyday', privacy='Privacy', help='Help', delete='Delete account', contact='Contact', by='An app by', status='Free app · iOS and Android release in preparation', rights='Jivie is not yet available in the app stores.') if en else dict(skip='Preskoči na vsebino', everyday='Za vsakdan', privacy='Zasebnost', help='Pomoč', delete='Izbris računa', contact='Kontakt', by='Aplikacijo razvija', status='Brezplačna aplikacija · izdaja za iOS in Android v pripravi', rights='Jivie še ni na voljo v trgovinah z aplikacijami.')
    target = ROOT / ('en' if en else '') / slug
    target.mkdir(parents=True, exist_ok=True)
    script = '<script src="/assets/deletion.js" defer></script>' if slug == 'delete-account' else ''
    target.joinpath('index.html').write_text(f'''<!doctype html>
<html lang="{lang}">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{escape(title)} · Jivie</title><meta name="description" content="{escape(description, quote=True)}">
<meta name="theme-color" content="#f5f7fb"><meta name="referrer" content="no-referrer">
<link rel="canonical" href="https://jivie.app{url(lang, slug)}">
<link rel="alternate" hreflang="sl" href="https://jivie.app{url('sl', slug)}"><link rel="alternate" hreflang="en" href="https://jivie.app{url('en', slug)}">
<meta property="og:type" content="website"><meta property="og:site_name" content="Jivie"><meta property="og:title" content="{escape(title, quote=True)} · Jivie"><meta property="og:description" content="{escape(description, quote=True)}"><meta property="og:image" content="https://jivie.app/assets/jivie-icon.png"><meta property="og:url" content="https://jivie.app{url(lang, slug)}">
<link rel="icon" type="image/png" href="/assets/jivie-icon.png"><link rel="apple-touch-icon" href="/assets/jivie-icon.png"><link rel="stylesheet" href="/assets/site.css">{script}
</head>
<body><a class="skip" href="#main">{text['skip']}</a><div class="wrap">
<header class="topbar">{brand(lang)}<nav class="nav" aria-label="{'Main navigation' if en else 'Glavna navigacija'}"><a class="home-extra" href="{url(lang)}#everyday">{text['everyday']}</a><a href="{url(lang, 'help')}">{text['help']}</a><a class="lang" href="{url(other, slug)}" lang="{other}" aria-label="{'Slovenščina' if en else 'English'}">{other.upper()}</a></nav></header>
<main id="main" {'class="article"' if not home else ''}>{content}</main>
<footer class="footer"><div>{brand(lang)}<p>{text['by']} <a href="https://triparna.si/" rel="noopener noreferrer">TriparNA</a>.</p><p>{text['status']}</p></div><nav class="footer-links" aria-label="{'Information' if en else 'Informacije'}"><a href="{url(lang, 'privacy')}">{text['privacy']}</a><a href="{url(lang, 'help')}">{text['help']}</a><a href="{url(lang, 'delete-account')}">{text['delete']}</a><a href="mailto:{EMAIL}">{text['contact']}</a></nav></footer>
<div class="legal-line">© 2026 TriparNA · {text['rights']}</div>
</div></body></html>''', encoding='utf-8')


def home(lang):
    en = lang == 'en'
    x = dict(eyebrow='Your day. Your plans. Your people.', title='Less on your mind.<br><span>More life.</span>', intro='The task you don’t want to forget. The plans you share. The little things that make a home. Bring them together in Jivie.', discover='Meet Jivie', start='How to start', free='Free to use', stores='iOS & Android · coming soon', today='Today', date='A little more room for your day.', next='UP NEXT', card='Make time for what matters', cardbody='Your plans, tasks and reminders in one place.', tasks='Your next steps', task1='Plan the weekend', task1sub='Personal plans', task2='Measure the new shelf', task2sub='A project at home', tag='Home', shop='Shopping, sorted', shopsub='A list to take with you', plans='Plans', shopping='Shopping', more='More', offline='Works offline, too', offlinesub='Your personal space, on your device.', sample='Illustration with example content.', p1='Start without an account', p2='Keep your personal data on your device', p3='Choose what you share', section='One place.<br>For the everyday.', sectionbody='From small errands to bigger projects. Jivie helps you see what’s ahead and keep the details together.', together='Some plans<br>are better shared.', togetherbody='Keep a space for yourself, a home for your household, or a project for the people involved. Share the right things with the right people.', togethernote='Sharing uses a compatible server you or your server operator manage. Your personal content stays private until you choose to share it.', personal='Just for you', personalsub='Your tasks, plans and personal finances', household='Your household', householdsub='Shared shopping, tasks and finances', project='A shared project', projectsub='Family, friends or other collaborators', local='Start here.<br>Stay in control.', stamp='Local first. At your pace.', closer='Good plans don’t need a subscription.', closerbody='Jivie is being prepared as a free app for iOS and Android. You can use it on its own or connect your own compatible server. Managed hosting is planned for a later stage.', closercta='Questions? Get in touch') if en else dict(eyebrow='Tvoj dan. Tvoji načrti. Tvoji ljudje.', title='Manj v glavi.<br><span>Več življenja.</span>', intro='Opravilo, ki ga nočeš pozabiti. Načrti, ki jih deliš. Malenkosti, ki sestavljajo dom. Zberi jih na enem mestu v Jivie.', discover='Spoznaj Jivie', start='Kako začnem', free='Brezplačna uporaba', stores='iOS in Android · v pripravi', today='Danes', date='Nekaj več prostora za tvoj dan.', next='NASLEDNJI KORAK', card='Čas za tisto, kar ti je pomembno', cardbody='Načrti, opravila in opomniki na enem mestu.', tasks='Tvoji naslednji koraki', task1='Načrt za konec tedna', task1sub='Osebni načrti', task2='Izmeri prostor za novo polico', task2sub='Projekt doma', tag='Dom', shop='Nakupi, na svojem mestu', shopsub='Seznam, ki gre s teboj', plans='Načrti', shopping='Nakupi', more='Več', offline='Deluje tudi brez povezave', offlinesub='Tvoj osebni prostor, na tvoji napravi.', sample='Ilustracija s primeri vsebine.', p1='Začni brez računa', p2='Osebne podatke hrani na napravi', p3='Sam izberi, kaj deliš', section='Eno mesto.<br>Za vsakdan.', sectionbody='Od majhnih opravkov do večjih projektov. Jivie ti pomaga videti, kaj te čaka, in ohraniti podrobnosti skupaj.', together='Nekateri načrti<br>so lepši skupaj.', togetherbody='Osebni prostor zase, dom za gospodinjstvo ali projekt za ljudi, ki sodelujejo pri njem. Deli prave stvari s pravimi ljudmi.', togethernote='Deljenje uporablja združljiv strežnik, za katerega skrbiš ti ali njegov upravljavec. Osebna vsebina ostane zasebna, dokler je ne deliš.', personal='Samo zate', personalsub='Tvoja opravila, načrti in osebne finance', household='Tvoj dom', householdsub='Skupni nakupi, opravila in finance', project='Skupni projekt', projectsub='Družina, prijatelji ali drugi sodelavci', local='Začni preprosto.<br>Nadaljuj po svoje.', stamp='Najprej lokalno. V tvojem ritmu.', closer='Za dober načrt ne potrebuješ naročnine.', closerbody='Jivie pripravljamo kot brezplačno aplikacijo za iOS in Android. Uporabljaš jo lahko samostojno ali povežeš lasten združljiv strežnik. Upravljano gostovanje načrtujemo za poznejšo fazo.', closercta='Piši nam')
    features = [('A calmer day','See upcoming tasks and events. Use reminders to make room for the things you want to remember.','Today'),('Plans that move forward','Keep tasks and deadlines together, from a weekend idea to the next project at home.','Plans'),('Shopping that comes along','Write a list, add what you need and check things off as you go. Share it with your household when connected.','Shopping'),('A clearer view of money','Record income and expenses. Keep personal finances separate, or explicitly share a financial space.','Finances'),('Know what’s happening','Find shared activity and assignments in your notification centre. Open the item the notification is about.','Notifications'),('A copy you can keep','Export an encrypted portable backup. Restore it when you change devices, using the password you chose.','Backups')] if en else [('Mirnejši pregled dneva','Poglej prihajajoča opravila in dogodke. Z opomniki naredi prostor za stvari, na katere želiš misliti.','Danes'),('Načrti, ki se premikajo','Opravila in roki skupaj: od zamisli za konec tedna do naslednjega domačega projekta.','Načrti'),('Nakupi, ki gredo s teboj','Napiši seznam, dodaj, kar potrebuješ, in odkljukaj opravljeno. Ob povezavi ga deli z gospodinjstvom.','Nakupi'),('Jasnejši pogled na denar','Zapiši prihodke in stroške. Osebne finance ohrani zase ali izrecno deli skupni finančni prostor.','Finance'),('Veš, kaj se dogaja','Skupno dogajanje in dodelitve te čakajo v centru obvestil. Iz obvestila odpri opravilo, na katero se nanaša.','Obvestila'),('Kopija, ki ostane pri tebi','Ustvari šifrirano prenosno kopijo. Ob menjavi naprave jo obnovi z geslom, ki si ga izbral.','Varnostne kopije')]
    steps = [('Open it. Start locally.','No account or server is needed for your personal plans, tasks, shopping and finances.'),('Add your first little thing.','A task for today, a shopping list, a plan for the weekend. Your own content sets the pace.'),('Connect when it makes sense.','Choose a compatible server for syncing and sharing. You decide which personal content to transfer.')] if en else [('Odpri in začni lokalno.','Za osebne načrte, opravila, nakupe in finance ne potrebuješ računa ali strežnika.'),('Dodaj prvo malenkost.','Opravilo za danes, nakupovalni seznam, načrt za konec tedna. Začni s svojo vsebino.'),('Poveži, ko ti pride prav.','Za sinhronizacijo in deljenje izberi združljiv strežnik. O prenosu osebne vsebine odločiš sam.')]
    cards=''.join(f'<article class="feature"><span class="feature-index">0{i}</span><h3>{a}</h3><p>{b}</p><span class="feature-label">{c}</span></article>' for i,(a,b,c) in enumerate(features,1))
    step_html=''.join(f'<li><span class="number">0{i}</span><div><strong>{a}</strong><p>{b}</p></div></li>' for i,(a,b) in enumerate(steps,1))
    content=f'''<section class="hero"><div><p class="eyebrow">{x['eyebrow']}</p><h1>{x['title']}</h1><p class="intro">{x['intro']}</p><div class="actions"><a class="button primary" href="#everyday">{x['discover']}<span class="arrow" aria-hidden="true">↗</span></a><a class="button" href="{url(lang,'help')}">{x['start']}</a></div><div class="availability"><span><i class="dot" aria-hidden="true"></i>{x['free']}</span><span>{x['stores']}</span></div></div>
<div class="phone-stage" role="img" aria-label="{'Illustrative Jivie mobile interface with example tasks and shopping. Not a screenshot.' if en else 'Ilustrativen mobilni vmesnik Jivie s primeri opravil in nakupov. Ni zaslonska slika.'}"><div class="halo"></div><div class="orbit"></div><div class="phone" aria-hidden="true"><div class="phone-top"><span>9:41</span><span class="island"></span><span>▰ ▪</span></div><div class="phone-main"><div class="phone-brand"><img src="/assets/jivie-icon.png" alt="">Jivie</div><h2>{x['today']}</h2><p class="phone-date">{x['date']}</p><div class="day-card"><span class="tiny-label">{x['next']}</span><h3>{x['card']}</h3><p>{x['cardbody']}</p></div><p class="mini-section">{x['tasks']}</p><div class="task-row"><span class="check"></span><div>{x['task1']}<small>{x['task1sub']}</small></div></div><div class="task-row"><span class="check"></span><div>{x['task2']}<small>{x['task2sub']}</small></div><span class="tag">{x['tag']}</span></div><div class="mini-shop"><span class="glyph">▤</span><div><b>{x['shop']}</b><small>{x['shopsub']}</small></div></div></div><div class="phone-nav"><span class="active"><b>◷</b>{x['today']}</span><span><b>▦</b>{x['plans']}</span><span><b>▤</b>{x['shopping']}</span><span><b>···</b>{x['more']}</span></div></div><div class="float-note" aria-hidden="true"><span class="note-icon">✓</span><div><strong>{x['offline']}</strong><small>{x['offlinesub']}</small></div></div><span class="illustration">{x['sample']}</span></div></section>
<div class="principles"><div><span class="num">01</span>{x['p1']}</div><div><span class="num">02</span>{x['p2']}</div><div><span class="num">03</span>{x['p3']}</div></div>
<section id="everyday" class="section"><div class="section-header"><h2>{x['section']}</h2><p>{x['sectionbody']}</p></div><div class="feature-grid">{cards}</div></section>
<section class="together"><div><p class="eyebrow">{'A place for your people' if en else 'Prostor za tvoje ljudi'}</p><h2>{x['together']}</h2><p>{x['togetherbody']}</p><p class="site-note">{x['togethernote']}</p><a class="text-link" href="{url(lang,'help')}#server">{'About connecting a server' if en else 'O povezovanju strežnika'} ↗</a></div><div class="scope-list"><div class="scope"><span class="scope-icon" aria-hidden="true">○</span><div><b>{x['personal']}</b><small>{x['personalsub']}</small></div><span class="scope-arrow" aria-hidden="true">↗</span></div><div class="scope"><span class="scope-icon" aria-hidden="true">⌂</span><div><b>{x['household']}</b><small>{x['householdsub']}</small></div><span class="scope-arrow" aria-hidden="true">↗</span></div><div class="scope"><span class="scope-icon" aria-hidden="true">◇</span><div><b>{x['project']}</b><small>{x['projectsub']}</small></div><span class="scope-arrow" aria-hidden="true">↗</span></div></div></section>
<section class="section local-section"><div class="local-visual"><img src="/assets/jivie-mark.png" alt="{'Jivie: earth, water and air intertwined' if en else 'Jivie: prepleteni zemlja, voda in zrak'}" width="350" height="350" loading="lazy"><span class="local-stamp">{x['stamp']}</span></div><div><p class="eyebrow">{'Local first' if en else 'Najprej na tvoji napravi'}</p><h2>{x['local']}</h2><ol class="steps">{step_html}</ol></div></section>
<section class="closing"><div><h2>{x['closer']}</h2><p>{x['closerbody']}</p></div><a class="button" href="mailto:{EMAIL}">{x['closercta']} <span aria-hidden="true">↗</span></a></section>'''
    page(lang,'','Less on your mind. More life.' if en else 'Manj v glavi. Več življenja.','A free local-first organizer for tasks, home projects, shopping and finances. iOS and Android release in preparation.' if en else 'Brezplačen lokalni organizator opravil, domačih projektov, nakupov in financ. Izdaja za iOS in Android je v pripravi.',content,True)


def privacy(lang):
    en=lang=='en'
    title='Data and privacy' if en else 'Podatki in zasebnost'
    sections=[
        ('Personal use, on your device','You can use Jivie for personal tasks, plans, shopping and finances without an account. These records are stored on your device. The active local database does not have additional encryption provided by the app; protection also depends on your device and operating system.'),
        ('Connecting your own server','For optional synchronization and sharing, you connect a compatible Kanboard server with the FamilyHub plugin. Signing in alone does not upload your personal content. You explicitly enable private synchronization; shared content is available according to the permissions of its space. The server processes account data, sessions, memberships, submitted content and technical data needed for operation and security. Its operator controls the deployment, logs, service providers and backups. TriparNA does not currently offer managed Jivie hosting.'),
        ('Reminders and notifications','Local reminders use your device’s notification system and permissions. The remote Firebase Cloud Messaging/APNs channel is not yet configured for the public release and is not automatically available for arbitrary self-hosted servers. Email delivery requires separate server configuration and may use a verified email address for security codes or enabled notifications.'),
        ('Optional AI','AI is an optional advanced feature in the legacy Kanboard part of the app. If you configure it and send content, your message and the project context you have allowed are sent to OpenAI using your API key. The local conversation history is kept in your profile. The personal organizer works without AI.'),
        ('Backups and exports','A portable .vsakdan backup is encrypted with a password you choose and saved to a location you select. It does not include login sessions or attachments and is not a complete server backup. The advanced JSON export is unencrypted. You control the copies you export and where they are stored.'),
        ('Deleting data',f'Signing out does not delete your account or all local data. See <a href="{url(lang,"delete-account")}">account deletion</a> for the self-hosted account process. Server deletion cannot recall copies other members already obtained or exports you saved elsewhere. Your server operator is responsible for the handling of its logs and backups. The deletion screen explains which active data is affected before confirmation.'),
        ('This website','This static website does not use analytics, advertising trackers or cookies set by its own code. Fonts, images and scripts are served from this website. The hosting infrastructure may process normal technical request data, such as IP addresses, to deliver and protect the site. Entering a server address on the deletion page only prepares a link in your browser; this page does not check your account or send login credentials. Opening the link connects you to the server you selected.'),
        ('Contact and requests',f'Jivie is published by {escape(PUBLISHER)}, Jablanica 18, 8294 Boštanj, Slovenia. For questions about the app, this website or privacy, contact <a href="mailto:{EMAIL}">{EMAIL}</a>. For access, correction or deletion of data on a self-hosted server, contact that server’s operator. Do not email passwords, sign-in codes, API keys or personal backups.')
    ] if en else [
        ('Osebna uporaba na tvoji napravi','Jivie lahko uporabljaš za osebna opravila, načrte, nakupe in finance brez računa. Ti zapisi se hranijo na napravi. Aktivna lokalna baza nima dodatnega šifriranja v aplikaciji; zaščita je odvisna tudi od naprave in operacijskega sistema.'),
        ('Povezava z lastnim strežnikom','Za izbirno sinhronizacijo in sodelovanje povežeš združljiv strežnik Kanboard z vtičnikom FamilyHub. Prijava sama ne prenese osebnih vsebin. Zasebni prenos omogočiš izrecno; skupna vsebina je dostopna glede na pravice prostora. Strežnik obdeluje podatke računa, seje, članstva, poslane vsebine ter tehnične podatke za delovanje in varnost. Njegov upravljavec določa konfiguracijo, dnevnike, ponudnike in varnostne kopije. TriparNA trenutno ne ponuja upravljanega gostovanja Jivie.'),
        ('Opomniki in obvestila','Lokalni opomniki uporabljajo sistem obvestil in dovoljenja naprave. Oddaljeni kanal Firebase Cloud Messaging/APNs še ni nastavljen za javno izdajo in pri poljubnem samostojnem gostovanju ni samodejno na voljo. E-pošta zahteva ločeno nastavitev strežnika in lahko uporablja preverjeni naslov za varnostne kode ali omogočena obvestila.'),
        ('Izbirni AI','AI je izbirna napredna možnost v starejšem Kanboard delu aplikacije. Če jo posebej nastaviš in pošlješ vsebino, se sporočilo ter dovoljeni projektni kontekst pošljeta k OpenAI s tvojim API ključem. Lokalna zgodovina pogovora ostane v profilu. Osebni organizator deluje brez AI.'),
        ('Varnostne kopije in izvozi','Prenosna kopija .vsakdan je šifrirana z geslom, ki ga izbereš, in shranjena na izbrano lokacijo. Ne vsebuje prijavnih sej ali priponk in ni popolna kopija strežnika. Napredni JSON izvoz je nešifriran. Izvožene kopije in mesto njihove hrambe upravljaš sam.'),
        ('Brisanje podatkov',f'Odjava ne izbriše računa ali vseh lokalnih podatkov. Postopek za samostojni strežnik je opisan na strani <a href="{url(lang,"delete-account")}">Izbris računa</a>. Strežniški izbris ne more odpoklicati kopij, ki so jih drugi člani že pridobili, ali izvozov, shranjenih drugje. Za ravnanje z dnevniki in varnostnimi kopijami strežnika je odgovoren njegov upravljavec. Zaslon za izbris pred potrditvijo pojasni, kateri aktivni podatki so vključeni.'),
        ('Ta spletna stran','Ta statična stran v svoji kodi ne uporablja analitike, oglaševalskih sledilnikov ali piškotkov. Pisave, slike in skripte se nalagajo s te strani. Infrastruktura gostovanja lahko za dostavo in zaščito strani obdeluje običajne tehnične podatke zahtev, na primer naslov IP. Vnos naslova strežnika na strani za izbris samo pripravi povezavo v brskalniku; stran ne preverja računa in ne pošilja prijavnih podatkov. Z odprtjem povezave se povežeš z izbranim strežnikom.'),
        ('Kontakt in zahtevki',f'Jivie izdaja {escape(PUBLISHER)}, Jablanica 18, 8294 Boštanj. Za vprašanja o aplikaciji, tej strani ali zasebnosti piši na <a href="mailto:{EMAIL}">{EMAIL}</a>. Za dostop, popravek ali izbris podatkov na samostojnem strežniku se obrni na njegovega upravljavca. Po e-pošti ne pošiljaj gesel, prijavnih kod, API ključev ali osebnih varnostnih kopij.')
    ]
    intro='How data is handled in the local app, on your own server and on this website.' if en else 'Kako ravnamo s podatki v lokalni aplikaciji, na tvojem strežniku in na tej spletni strani.'
    content=f'<p class="eyebrow">Jivie · {"7 October 2026" if en else "7. oktober 2026"}</p><h1>{title}</h1><p class="lead">{intro}</p>'+''.join(f'<section><h2>{h}</h2><p>{p}</p></section>' for h,p in sections)
    page(lang,'privacy',title,intro,content)


def help_page(lang):
    en=lang=='en'
    title='A small guide to getting started' if en else 'Majhen vodič za dober začetek'
    intro='Start with one useful thing. Connect the rest when you need it.' if en else 'Začni z eno uporabno stvarjo. Ostalo poveži, ko ti pride prav.'
    items=[('Do I need an account?','No. Choose local use and create your first task, plan or shopping list. Personal work is saved on your device, even without a connection.','local'),('Where do I find things?','Today shows what is coming up. Plans brings tasks, projects and events together. Shopping keeps your lists at hand. More opens finances, settings and options for connecting and sharing. On desktop, these areas appear in the sidebar.','navigation'),('How do I keep a backup?','Open backups in the app and create an encrypted portable copy. Keep its password safe: the backup cannot be restored without it. Before changing devices, check that you can restore the copy. Synchronization is not a backup.','backup'),('How do I share with others?','Connect an HTTPS Kanboard server with the compatible FamilyHub plugin and its Native API enabled. The server operator prepares the first account or an invitation. Use your own account to join a shared home or project. A Kanboard server without the plugin does not provide these collaboration features. Connecting does not automatically upload your personal content.','server'),('What about notifications?','Local reminders need notification permission and a record available on the device. The shared notification centre refreshes when connected or synchronized. Remote phone notifications with the app closed are not automatically available for every self-hosted server.','notifications'),('What if I cannot sign in?','Check your server address and contact the server operator. Email password recovery requires server support and a previously verified email address. Never send your password or one-time codes to support.','login')]
    if not en:
        items=[('Ali potrebujem račun?','Ne. Izberi lokalno uporabo in dodaj prvo opravilo, načrt ali nakupovalni seznam. Osebno delo se shrani na napravi, tudi brez povezave.','local'),('Kje najdem posamezne stvari?','Danes pokaže, kaj te čaka. Načrti povežejo opravila, projekte in dogodke. Nakupi hranijo tvoje sezname. V Več najdeš finance, nastavitve ter možnosti povezovanja in deljenja. Na namizju so ta področja v stranskem meniju.','navigation'),('Kako ohranim varnostno kopijo?','V aplikaciji odpri kopije in ustvari šifrirano prenosno kopijo. Geslo shrani varno: brez njega kopije ne moreš obnoviti. Pred menjavo naprave preveri, da obnova deluje. Sinhronizacija ni varnostna kopija.','backup'),('Kako delim z drugimi?','Poveži HTTPS strežnik Kanboard z združljivim vtičnikom FamilyHub in omogočenim Native API. Prvi račun ali povabilo pripravi upravljavec strežnika. S svojim računom se pridruži skupnemu domu ali projektu. Kanboard brez vtičnika teh možnosti sodelovanja ne zagotavlja. Povezovanje osebne vsebine ne prenese samodejno.','server'),('Kako delujejo obvestila?','Lokalni opomniki potrebujejo dovoljenje za obvestila in zapis, ki je na napravi. Center skupnih obvestil se osveži ob povezavi oziroma sinhronizaciji. Oddaljena telefonska obvestila ob zaprti aplikaciji niso samodejno na voljo za vsak samostojni strežnik.','notifications'),('Kaj če se ne morem prijaviti?','Preveri naslov strežnika in se obrni na njegovega upravljavca. Obnova gesla po e-pošti potrebuje podporo strežnika in predhodno preverjen naslov. Podpori nikoli ne pošiljaj gesla ali enkratnih kod.','login')]
    body=''.join(f'<section id="{id}"><h2>{q}</h2><p>{a}</p></section>' for q,a,id in items)
    body+=f'<section><h2>{"How do I delete my account?" if en else "Kako izbrišem račun?"}</h2><p><a href="{url(lang,"delete-account")}">{"See the self-hosted account deletion process." if en else "Odpri postopek izbrisa računa na samostojnem strežniku."}</a></p></section>'
    body+=f'<section><h2>{"Need a hand?" if en else "Potrebuješ pomoč?"}</h2><p>{"Tell us the app version, your operating system and what happened. Remove personal data from screenshots." if en else "Opiši težavo, različico aplikacije in operacijski sistem. Iz posnetkov odstrani osebne podatke."} <a href="mailto:{EMAIL}">{EMAIL}</a>.</p></section>'
    page(lang,'help',title,intro,f'<p class="eyebrow">Jivie · {"Help" if en else "Pomoč"}</p><h1>{title}</h1><p class="lead">{intro}</p>{body}')


def delete_page(lang):
    en=lang=='en'
    title='Delete your self-hosted account' if en else 'Izbris računa na lastnem strežniku'
    intro='The process takes place on the server where your account lives.' if en else 'Postopek poteka na strežniku, kjer imaš svoj račun.'
    body=f'''<p class="eyebrow">Jivie · {"Account and data" if en else "Račun in podatki"}</p><h1>{title}</h1><p class="lead">{intro}</p>
<p>{'Local-only use has no server account. This page is for accounts on a self-hosted Kanboard server with the FamilyHub plugin. TriparNA cannot access those accounts simply because you use Jivie.' if en else 'Pri uporabi samo na napravi strežniškega računa nimaš. Ta stran velja za račune na samostojnem strežniku Kanboard z vtičnikom FamilyHub. TriparNA do teh računov nima dostopa samo zato, ker uporabljaš Jivie.'}</p>
<div class="notice"><p>{'Export what you want to keep before deletion. Jivie currently uses the same user account as Kanboard: deleting that account also removes its Kanboard sign-in. Signing out or uninstalling the app does not delete the server account.' if en else 'Pred izbrisom izvozi, kar želiš ohraniti. Jivie trenutno uporablja isti uporabniški račun kot Kanboard: izbris tega računa odstrani tudi njegovo prijavo v Kanboard. Odjava ali odstranitev aplikacije nista izbris strežniškega računa.'}</p></div>
<h2>{'Open your server’s deletion page' if en else 'Odpri stran za izbris na svojem strežniku'}</h2>
<p>{'Enter only the base address of your Kanboard server. This page prepares a link; it does not connect to the server or send a deletion request. You sign in and confirm on your own server.' if en else 'Vnesi samo osnovni naslov svojega Kanboard strežnika. Ta stran pripravi povezavo; ne poveže se s strežnikom in ne pošlje zahteve za izbris. Prijavo in potrditev opraviš na svojem strežniku.'}</p>
<form class="server-form" data-server-form data-error-message="{'Enter an HTTPS base address without a username, password, query, fragment or index.php. Example: https://board.example.org/kanboard/' if en else 'Vnesi osnovni HTTPS naslov brez uporabniškega imena, gesla, parametrov, fragmenta ali index.php. Primer: https://board.example.org/kanboard/'}"><label for="server">{'Your server address' if en else 'Naslov tvojega strežnika'}</label><input id="server" type="url" inputmode="url" autocomplete="off" spellcheck="false" required placeholder="https://board.example.org/kanboard/" aria-describedby="server-hint server-error"><p class="hint" id="server-hint">{'Do not enter passwords, sign-in codes or invitation links here.' if en else 'Sem ne vpisuj gesel, prijavnih kod ali povezav s povabili.'}</p><button class="button primary" type="submit">{'Prepare link' if en else 'Pripravi povezavo'} <span aria-hidden="true">↗</span></button><p class="error" id="server-error" data-error role="alert"></p><div class="server-result" data-result hidden><p>{'Continue on:' if en else 'Nadaljuješ na:'} <strong data-host></strong></p><a class="button primary" data-server-link target="_blank" rel="noopener noreferrer">{'Open my server' if en else 'Odpri moj strežnik'} ↗</a><p class="hint">{'Check the address before signing in. A compatible FamilyHub version with account deletion enabled is required.' if en else 'Pred prijavo preveri naslov. Potrebna je združljiva različica FamilyHub z omogočenim izbrisom računa.'}</p></div><noscript><p>{'Enable JavaScript to prepare the link, or open your Kanboard server and use its FamilyHub account deletion page. No password should be entered on jivie.app.' if en else 'Za pripravo povezave omogoči JavaScript ali odpri svoj Kanboard strežnik in njegovo stran FamilyHub za izbris računa. Na jivie.app ne vpisuj gesla.'}</p></noscript></form>
<h2>{'Before you confirm' if en else 'Pred potrditvijo'}</h2><p>{'Your server shows the affected data and any ownership issues that need resolving. Personal synchronized data, access and shared contributions are handled according to that preview. Shared spaces or records belonging to other people must not disappear as a hidden side effect. The process may require an ownership transfer or an explicit choice for shared structures.' if en else 'Strežnik pokaže prizadete podatke in morebitna lastništva, ki jih je treba urediti. Sinhronizirani osebni podatki, dostop in skupni prispevki se obravnavajo po tem predogledu. Prostori ali zapisi drugih ljudi ne smejo izginiti kot skrita posledica. Postopek lahko zahteva prenos lastništva ali izrecno izbiro za skupne strukture.'}</p>
<p>{'Records created by other members remain, including edits you made to their content. A shared shopping list or financial account needed by other members can remain after an explicit choice, with identifying fields removed; the preview explains any retained balance. Some older Kanboard tasks contain contributions from several people and require resolving those dependencies before deletion.' if en else 'Zapisi, ki so jih ustvarili drugi člani, ostanejo, tudi z vašimi popravki njihove vsebine. Skupni nakupovalni seznam ali finančni račun, ki ga potrebujejo drugi člani, lahko po izrecni izbiri ostane z odstranjenimi osebnimi oznakami; predogled pojasni tudi morebitno ohranjeno stanje. Pri nekaterih starejših Kanboardovih opravilih s prispevki več ljudi je treba pred izbrisom najprej urediti te odvisnosti.'}</p>
<h2>{'If your server does not support this page' if en else 'Če strežnik te strani še ne podpira'}</h2><p>{'Ask its operator to update FamilyHub and enable the self-hosted deletion feature. This public site cannot perform deletion on an incompatible or unreachable server and does not show a deletion as complete without that server’s confirmation.' if en else 'Upravljavca prosi za nadgradnjo FamilyHub in vključitev izbrisa za samostojno gostovanje. Ta javna stran ne more izvesti izbrisa na nezdružljivem ali nedosegljivem strežniku in ne prikazuje izbrisa kot opravljenega brez njegove potrditve.'}</p>
<h2>{'Copies and backups' if en else 'Kopije in varnostne kopije'}</h2><p>{'Deletion cannot recall exports or copies other members already obtained. The server operator handles logs and server backups. Standalone local personal data is separate from the server account. Managed hosting is not offered at this stage and will have its own published rules if introduced.' if en else 'Izbris ne more odpoklicati izvozov ali kopij, ki so jih drugi člani že pridobili. Dnevnike in strežniške varnostne kopije ureja upravljavec strežnika. Samostojni lokalni osebni podatki so ločeni od strežniškega računa. Upravljanega gostovanja v tej fazi ne ponujamo; ob uvedbi bo imelo svoja objavljena pravila.'}</p>
<p>{'Questions about the app?' if en else 'Vprašanja o aplikaciji?'} <a href="mailto:{EMAIL}">{EMAIL}</a>.</p>'''
    page(lang,'delete-account',title,intro,body)


def main():
    for lang in ('sl','en'):
        home(lang); privacy(lang); help_page(lang); delete_page(lang)
    urls=''.join(f'<url><loc>https://jivie.app{url(lang,slug)}</loc></url>' for lang in ('sl','en') for slug in ('','privacy','help','delete-account'))
    ROOT.joinpath('sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+urls+'</urlset>\n',encoding='utf-8')
    print('Rendered 8 static pages into website/public/.')


if __name__ == '__main__':
    main()
